INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1', 'Danantara Housing Expo 2026 Hadirkan 200.000 Hunian, Dukung Program 3 Juta Rumah', 'Industri', '29 JULI 2026, 21.04', 2457, 'Danantara Housing Expo 2026 digelar di ICE BSD PK 2, 27-30 Agustus 2026, untuk mendukung Program 3 Juta Rumah.', 'Pemerintah bersama Badan Pengelola Investasi Danantara menggelar Danantara Housing Expo 2026 di Hall 3-5 ICE BSD. Pameran properti terbesar tahun ini menghadirkan lebih dari 200.000 unit hunian terjangkau untuk masyarakat berpenghasilan rendah (MBR) maupun generasi muda.\n\nLangkah ini merupakan perwujudan konkret dalam mendukung pencapaian Program 3 Juta Rumah yang dicanangkan pemerintah pusat.\n\nDalam pameran ini, calon pembeli disuguhkan suku bunga KPR subsidi tetap 5% hingga tenor 20 tahun serta bebas biaya provisi dan administrasi perbankan.', 'Siti Rahmawati', 'https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 0, '["Properti","Danantara","KPR Subsidised","Industri"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785585918910', 'ASQINEWS Resmi Mengudara Sebagai Pusat Rujukan Data Pelayanan Publik Indonesia', 'Berita Terbaru', '3 AGUSTUS 2026, 21.09', 7, 'JAKARTA,ASQINEWS.com - \nPortal berita digital ASQINEWS resmi mengudara Senin 2 Agustus 2026. Berbeda dari media arus utama yang masih didominasi polit...', 'JAKARTA,ASQINEWS.com - \nPortal berita digital ASQINEWS resmi mengudara Senin 2 Agustus 2026. Berbeda dari media arus utama yang masih didominasi politik, kriminal dan hiburan, ASQINEWS hadir dengan fokus tunggal yaitu menjadi pusat informasi, pusat data, dan pusat rujukan Nasional di bidang pelayanan publik.\n\nKehadiran ASQINEWS menjawab kebutuhan yang selama ini belum terisi. Pemerintah dan BUMN kesulitan mempublikasikan kinerja pelayanan secara objektif dan terukur. Di sisi lain masyarakat juga sulit mendapatkan informasi yang jelas, cepat dan berbasis data terkait layanan dasar.\n\n"ASQINEWS tidak hadir untuk menambah bising. Kami datang untuk menjembatani. Pemerintah butuh ruang kredibel untuk menunjukkan praktik baik. Masyarakat butuh data dan penjelasan yang bisa dipakai untuk memahami haknya," ujar Ahmad Arwani R, Pendiri ASQINEWS sekaligus Ketua Umum Asosiasi Service Quality Indonesia.\n\nArwani menegaskan ASQINEWS tidak akan terjebak pada pemberitaan yang hanya menyorot kesalahan.\n\n"Kami memegang tiga prinsip. Pertama, objektif dan solutif. Setiap persoalan kami angkat, lalu kami cari jalan keluarnya dan kami bandingkan dengan praktik baik di daerah lain. Kedua, berbasis data. Kami menggunakan angka IKM, SPBE, SAKIP, laporan Ombudsman, dan regulasi. Ketiga, berbasis lapangan. Tim jurnalis kami turun langsung ke lembaga dan Instansi, hingga wilayah 3T dan perbatasan," katanya.\n\nUntuk menjalankan misi itu, ASQINEWS menyiapkan empat jalur kerja.\n\nPertama, program harian dengan target 50 sampai 100 berita. Isinya pelayanan daerah, kebijakan pusat, BUMN, BUMD, dan suara warga. Tujuannya agar ASQINEWS menjadi rujukan utama di mesin pencari ketika orang mencari informasi pelayanan.\n\nKedua, program mingguan Sepekan ASQI di Kabupaten. Selama tujuh hari satu kabupaten dibedah tuntas. Outputnya berupa puluhan berita, video, dan satu majalah digital.\n\nKetiga, program bulanan Forum Humas Pelayanan Prima. Ini menjadi ruang edukasi, diskusi, dan sertifikasi bagi humas pemerintah, BUMN, BUMD, dan korporasi.\n\nKeempat, program triwulan Ekspedisi Jurnalistik Nusantara. Tim akan menyusuri daerah tertinggal dan perbatasan untuk merekam langsung kondisi pelayanan Negara.\n\n"Kami ingin ketika seorang menteri membutuhkan data pelayanan, dia membuka ASQINEWS. Ketika warga ingin mengadu atau mencari prosedur, mereka juga ke ASQINEWS. Itu posisi yang kami bangun," tambah Arwani.\n\nASQINEWS berada di bawah ekosistem ASQI dengan bimbingan Dewan Pakar Nasional. Redaksi berkomitmen bekerja berdasarkan Undang-Undang Pers, Undang-Undang Pelayanan Publik, Undang-Undang Keterbukaan Informasi Publik, dan Kode Etik Jurnalistik.\n\nPada hari pertama peluncuran, 50 artikel perdana telah tayang. Target enam bulan ke depan, ASQINEWS masuk tiga besar hasil pencarian Google untuk kata kunci pelayanan publik.\n\nWebsite asqinews.com kini dapat diakses secara gratis oleh seluruh masyarakat Indonesia.\n\nTENTANG ASQINEWS\nASQINEWS adalah media pers digital Nasional yang berfokus pada pelayanan publik. Visi ASQINEWS adalah menjadi media terdepan, terpercaya, dan paling berpengaruh dalam mengawal peningkatan kualitas pelayanan publik demi kesejahteraan masyarakat di seluruh pelosok tanah air.\n(Redaksi ASQINEWS).', 'Super Admin ASQI', 'https://images.unsplash.com/photo-1504711434969-e33886168f5c?auto=format&fit=crop&w=1000&q=80', '', '', '', 1, 1, '["Finansial"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785757212327', 'Ahmad Arwani dan Misi Membangun Ekosistem Pelayanan Publik Lewat ASQINEWS', 'Berita Terbaru', '3 AGUSTUS 2026, 18.40', 178, 'Sebagai Pendiri ASQINEWS dan Ketua Umum ASQI, ia mengembangkan ekosistem media yang menghubungkan pemerintah, BUMN, dunia usaha, dan masyarakat melalui jurnalisme berbasis data serta pendekatan yang solutif.', 'JAKARTA, ASQINEWS.com – Di tengah persaingan media digital yang didominasi pemberitaan politik, hukum, kriminal, dan hiburan, hadir sebuah portal berita dengan fokus yang lebih spesifik. ASQINEWS.com resmi diluncurkan sebagai media yang mengusung pelayanan publik sebagai tema utama pemberitaan.\n\nPortal berita ini didirikan oleh Ahmad Arwani R, praktisi di bidang transformasi organisasi dan peningkatan kualitas pelayanan yang kini menjabat sebagai Pendiri ASQINEWS sekaligus Ketua Umum Asosiasi Service Quality Indonesia (ASQI).\n\nBagi Ahmad Arwani, lahirnya ASQINEWS merupakan kelanjutan dari perjalanan profesionalnya selama lebih dari satu dekade mendampingi kementerian, pemerintah daerah, BUMN, BUMD, dan berbagai organisasi dalam meningkatkan kualitas pelayanan kepada masyarakat.\n\n"Instansi sudah bekerja dan memiliki banyak capaian, tetapi informasi itu tidak selalu tersampaikan kepada masyarakat secara utuh. Di sisi lain, masyarakat membutuhkan informasi pelayanan yang akurat, mudah dipahami, dan dapat dipertanggungjawabkan. Di situlah kami melihat perlunya media yang secara khusus mengawal isu pelayanan publik," ujar Ahmad Arwani.\n\nPerjalanan karier Ahmad Arwani dimulai di dunia industri. Lulusan Sarjana Teknik Mesin Universitas Diponegoro dan Magister Manajemen PPM School of Management Jakarta itu pernah menjabat sebagai Head of Service Logistics Operation Acer Indonesia pada periode 2007–2011. Dalam posisi tersebut, ia bertanggung jawab memastikan distribusi suku cadang dan pemenuhan standar tingkat layanan (service level agreement/SLA) bagi jaringan layanan nasional perusahaan.\n\nSelanjutnya, ia bergabung dengan Kinsani–Dunamis Organisation Services Group sebagai Head of Product & Business Development. Di perusahaan tersebut, ia memimpin pengembangan berbagai program pelatihan sekaligus membangun kemitraan strategis dengan VitalSmarts.\n\nPada 2015, Ahmad Arwani mendirikan Kinerja Unggul Nusantara. Sebagai Founder dan Chief Executive Officer (CEO), ia memimpin perusahaan konsultan yang memberikan pendampingan transformasi organisasi dan peningkatan kinerja kepada berbagai institusi, antara lain Pertamina Group, PLN, Pos Indonesia, BRI, BNI, Bank Mandiri, Telkomsel, BPJS Ketenagakerjaan, hingga Angkasa Pura I.\n\nPengalaman mendampingi berbagai institusi tersebut mempertemukannya dengan persoalan yang sama, yakni masih terbatasnya ruang pemberitaan yang secara konsisten mengulas kualitas pelayanan publik berdasarkan data dan fakta lapangan.\n\nBerangkat dari pengalaman itu, Ahmad Arwani mendirikan ASQI sebagai wadah pengembangan kualitas pelayanan sekaligus membangun ASQINEWS sebagai media yang mengedepankan jurnalisme berbasis solusi.\n\nASQINEWS diposisikan sebagai pusat rujukan informasi pelayanan publik di Indonesia. Dalam operasional redaksinya, media ini mengusung tiga prinsip utama, yaitu objektif dan solutif, berbasis data, serta berbasis lapangan.\n\nPendekatan objektif dan solutif diwujudkan melalui pemberitaan yang tidak hanya mengungkap persoalan, tetapi juga menghadirkan konteks, praktik baik, dan alternatif penyelesaian. Sementara itu, pendekatan berbasis data dilakukan dengan menyajikan indikator-indikator pelayanan seperti Indeks Kepuasan Masyarakat (IKM), Sistem Pemerintahan Berbasis Elektronik (SPBE), Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP), serta indikator lain yang relevan sesuai ketentuan peraturan perundang-undangan.\n\nAdapun pendekatan berbasis lapangan diwujudkan melalui peliputan langsung di berbagai titik pelayanan publik, mulai dari rumah sakit, kantor pelayanan administrasi kependudukan, kantor kecamatan, hingga wilayah tertinggal, terdepan, dan terluar (3T).\n\nUntuk menjalankan misi tersebut, ASQINEWS menyiapkan empat program utama yang dilaksanakan secara berjenjang.\n\nProgram harian berfokus pada penerbitan berita pelayanan publik secara konsisten setiap hari. Program mingguan bertajuk "Sepekan ASQINEWS di Kabupaten" mengulas secara komprehensif kualitas pelayanan publik di satu daerah selama tujuh hari berturut-turut.\n\nSelanjutnya, Program Bulanan diwujudkan melalui Forum Humas Pelayanan Prima yang menghadirkan webinar, diskusi, dan pengembangan kompetensi bagi praktisi komunikasi publik. Sementara itu, Program Triwulan dikemas dalam Ekspedisi Jurnalistik Nusantara yang mengangkat kondisi pelayanan publik di wilayah perbatasan dan daerah 3T.\n\nSelain produk jurnalistik, ASQINEWS juga mengembangkan berbagai layanan pendukung berupa Pusat Data ASQINEWS yang memuat indikator pelayanan publik, Pusat Regulasi yang menghimpun berbagai ketentuan perundang-undangan, Akademi ASQI sebagai wadah pelatihan dan sertifikasi, serta Peta Pelayanan Indonesia dan Direktori Instansi.\n\nDi luar aktivitas profesionalnya, Ahmad Arwani juga dikenal sebagai penulis di bidang logistik, manajemen, pelayanan, dan pengalaman pelanggan. Sejumlah buku yang telah diterbitkannya antara lain Warehouse Check Up, Panduan dan Direktori Logistik Indonesia, Creating Unforgettable Customer Experience, serta The Power of Execution.\n\nIa juga aktif dalam pengembangan sertifikasi profesi. Saat ini ia menjabat sebagai Chairman Certification Scheme bidang Logistics and Supply Chain Management pada LSP PPM Jakarta serta Chairman Certification Scheme bidang Public Service pada LSP Manajemen Pelayanan Indonesia. Berbagai sertifikasi profesional yang dimilikinya antara lain Certified Master Trainer BNSP, Certified Customer Experience Assessor, dan Certified Supply Chain Practitioner.\n\nAtas kiprahnya di bidang pelayanan dan logistik, Ahmad Arwani pernah menerima penghargaan 3rd Winner Logistics Innovation dari Asosiasi Logistik Indonesia serta Best Employee Acer Indonesia pada 2008 dan 2009.\n\nMenurut Ahmad Arwani, pelayanan publik merupakan fondasi penting dalam membangun kepercayaan masyarakat terhadap institusi.\n\n"Ketika masyarakat mengetahui standar pelayanan dan penyelenggara layanan memahami ruang perbaikannya, proses peningkatan kualitas pelayanan akan berjalan lebih cepat. Kami berharap ASQINEWS dapat menjadi jembatan yang mempertemukan kepentingan masyarakat dengan semangat perbaikan yang dilakukan berbagai institusi," katanya.\n\nKe depan, ASQINEWS menargetkan diri menjadi salah satu rujukan informasi mengenai pelayanan publik bagi pemerintah pusat, pemerintah daerah, BUMN, BUMD, kalangan akademisi, pelaku usaha, maupun masyarakat luas melalui penyajian informasi yang berimbang, berbasis data, dan berorientasi pada kepentingan publik.\n\nTentang ASQINEWS\n\nASQINEWS.com merupakan portal berita digital nasional yang berada dalam ekosistem Asosiasi Service Quality Indonesia (ASQI). Dalam menjalankan kegiatan jurnalistik, ASQINEWS berpedoman pada Undang-Undang Nomor 40 Tahun 1999 tentang Pers, Undang-Undang Nomor 25 Tahun 2009 tentang Pelayanan Publik, Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik, serta Kode Etik Jurnalistik.\n\nASQINEWS mengusung visi menjadi media pers nasional yang terpercaya dalam mengawal peningkatan kualitas pelayanan publik di Indonesia melalui pemberitaan yang akurat, berbasis data, dan berorientasi pada kepentingan masyarakat.', 'Super Admin ASQI', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=1000&q=80', '', '', '', 1, 1, '["Berita Terbaru"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785757884590', 'ASQI Luncurkan ASQINEWS sebagai Portal Berita untuk Mengawal Mutu Layanan di Seluruh Indonesia', 'Berita Terbaru', '3 AGUSTUS 2026, 18.51', 3, 'ASQI Luncurkan ASQINEWS sebagai Portal Berita untuk Mengawal Mutu Layanan di Seluruh Indonesia', 'JAKARTA, ASQINEWS.com - Portal berita digital ASQINEWS.com yang resmi diluncurkan pada Senin, 03 Agustus 2026, hadir sebagai perluasan dari gerakan yang lebih dulu dirintis oleh Asosiasi Service Quality Indonesia atau ASQI.\n\nASQI didirikan pada awal 2021. Organisasi ini lahir sebagai respons terhadap Inpres Nomor 12 Tahun 2016 tentang Gerakan Nasional Revolusi Mental. Salah satu amanatnya adalah Gerakan Indonesia Melayani.\n\nDengan tagline Indonesia Lebih Melayani, ASQI selama ini fokus pada tiga hal utama. Membangun standar nasional pelayanan, mengembangkan metode pengukuran, serta memfasilitasi pelatihan dan sertifikasi bagi aparatur pemerintah, BUMN, BUMD dan korporasi.\n\nKetua Umum ASQI sekaligus Pendiri ASQINEWS, Ahmad Arwani R, menjelaskan bahwa pendirian ASQINEWS merupakan jawaban atas tantangan komunikasi pelayanan publik di Indonesia.\n\n"Selama lima tahun terakhir kami mendampingi berbagai instansi pemerintah, BUMN, dan BUMD dalam upaya peningkatan kualitas layanan. Kami menemukan ada praktik baik yang sudah berjalan, namun belum cukup mendapat ruang publikasi yang memadai. Di sisi lain masyarakat juga membutuhkan akses informasi yang cepat dan berbasis data terkait pelayanan," ujar Arwani.\n\nArwani menegaskan ASQINEWS tidak hadir untuk sekadar memberitakan. Media ini dirancang menjadi bagian dari ekosistem perbaikan pelayanan secara sistemik.\n\n"Jika ASQI adalah rumah bagi pengembangan standar, pelatihan, dan sertifikasi, maka ASQINEWS adalah kanal publiknya. Fungsinya menyampaikan praktik baik, menyajikan data kinerja, dan melakukan pengawasan agar pelaksanaan Undang-Undang Pelayanan Publik berjalan sesuai amanat. Kami ingin ASQINEWS menjadi rujukan, baik bagi pengambil kebijakan maupun masyarakat," katanya.\n\nVisi ASQI adalah menjadi lembaga asosiasi profesi yang memberi nilai melalui peningkatan standar dan penciptaan budaya layanan prima. Visi itu kini diperkuat melalui ASQINEWS yang membawa empat misi besar. Mendukung penyelenggara agar lebih mau dan mampu melayani prima. Mengembangkan standar. Mengembangkan metode pengukuran. Serta membangun kemitraan untuk pembelajaran berkelanjutan.\n\nDengan struktur Dewan Pimpinan Pusat dan bimbingan Dewan Pakar Nasional, ASQI kini memiliki ekosistem yang lengkap. Ada ASQI sebagai pusat pembinaan dan sertifikasi. Ada Akademi ASQI untuk pelatihan. Ada Pusat Data untuk transparansi. Dan kini ada ASQINEWS sebagai media rujukan nasional.\n\n"Perubahan dalam pelayanan publik tidak cukup hanya dilakukan melalui pembinaan. Diperlukan pula ruang publik, data yang terbuka, dan pemberitaan yang solutif. ASQINEWS hadir untuk mengisi kekosongan itu," tegas Arwani.\n\nDengan demikian, kehadiran ASQINEWS melengkapi mimpi besar ASQI sejak awal berdiri. Yaitu mewujudkan Indonesia yang lebih melayani.\n\nTENTANG ASQI\nAsosiasi Service Quality Indonesia adalah organisasi profesi yang berfokus pada peningkatan kualitas pelayanan publik di Indonesia. ASQI mendukung Gerakan Indonesia Melayani melalui standarisasi, pengukuran, pelatihan, dan sertifikasi.\n(Redaksi ASQINEWS).', 'Super Admin ASQI', 'https://images.unsplash.com/photo-1495020689067-958852a7765e?auto=format&fit=crop&w=1000&q=80', '', '', '', 1, 1, '["Berita Terbaru"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785827637073', 'PM Thailand Janji Percepat Pemulangan 500 WNI Korban Online Scam, Prabowo: Bukti Eratnya Hubungan Dua Negara', 'Nasional', '4 AGUSTUS 2026, 14.13', 2, 'JAKARTA, ASQINEWS.com – Perdana Menteri Thailand Anutin Charnvirakul berkomitmen mempercepat pemulangan sekitar 500 warga negara Indonesia (WNI) yang ...', 'JAKARTA, ASQINEWS.com – Perdana Menteri Thailand Anutin Charnvirakul berkomitmen mempercepat pemulangan sekitar 500 warga negara Indonesia (WNI) yang menjadi korban tindak pidana penipuan daring (online scam).\n\nKomitmen tersebut disampaikan Anutin saat melakukan pertemuan bilateral dengan Presiden Prabowo Subianto di Istana Merdeka, Jakarta, Senin (3/8/2026), dalam rangka kunjungan kenegaraannya ke Indonesia pada 3–4 Agustus 2026.\n\n"Pemerintah saya akan mempercepat kepulangan mereka ke Indonesia," ujar Anutin dalam pernyataannya kepada Presiden Prabowo.\n\nDalam pertemuan tersebut, Anutin menegaskan bahwa Indonesia dan Thailand menghadapi tantangan yang sama terkait kejahatan lintas negara. Ia secara khusus menyoroti tiga bentuk kejahatan transnasional yang menjadi perhatian kedua negara, yakni penipuan daring, perdagangan orang, dan peredaran narkotika.\n\nMenurut Anutin, pemerintah Thailand siap memperkuat kerja sama dengan Indonesia melalui peningkatan koordinasi penegakan hukum, pertukaran informasi intelijen, peningkatan kapasitas aparat, hingga mempererat kerja sama di tingkat regional.\n\n"Dalam hal ini, kami akan lebih banyak bekerja sama, baik dari segi penegakan hukum, pertukaran informasi intelijen, penguatan kapasitas aparat, serta membangun kerja sama di tingkat kawasan," katanya.\n\nPresiden Prabowo menyambut baik komitmen tersebut. Ia menyampaikan apresiasi kepada Pemerintah Thailand yang selama ini telah membantu proses pemulangan hampir 1.000 WNI yang menjadi korban jaringan online scam di negara tersebut.\n\nMenurut Prabowo, bantuan yang diberikan Thailand mencerminkan eratnya hubungan persahabatan dan kerja sama kedua negara.\n\n"Ini bantuan yang sangat berarti. Ini membuktikan eratnya hubungan antara Indonesia dan Thailand. Sekali lagi Yang Mulia, atas nama bangsa dan rakyat Indonesia, saya ucapkan terima kasih dan apresiasi sebesar-besarnya," ujar Prabowo.\n\nSelain membahas penanganan korban online scam, kedua pemimpin juga menyepakati penguatan kerja sama di bidang keamanan dan pertahanan. Kerja sama tersebut akan dioptimalkan melalui mekanisme Indonesia-Thailand High Level Committee dan Indonesia-Thailand Security Dialogue yang selama ini menjadi forum koordinasi strategis kedua negara.\n\nDalam pernyataan bersama, Prabowo mengatakan bahwa tantangan keamanan kawasan, termasuk kejahatan lintas batas, hanya dapat diatasi melalui kolaborasi yang lebih erat antarnegara.\n\n"Kami mendorong untuk terus mengoptimalkan mekanisme yang ada bagi penguatan kerja sama pada isu-isu keamanan dan pertahanan, termasuk melalui Indonesia-Thailand High Level Committee dan Indonesia-Thailand Security Dialogue," kata Prabowo.\n\nKe depan, Indonesia dan Thailand juga sepakat meningkatkan kerja sama dalam pertukaran informasi intelijen, pelaksanaan investigasi bersama, pelacakan aliran dana dan transaksi keuangan mencurigakan, serta memperkuat koordinasi antar-aparat penegak hukum guna membongkar jaringan kejahatan lintas negara.\n\nKesepakatan tersebut diharapkan dapat memperkuat upaya kedua negara dalam melindungi warga negara sekaligus menekan aktivitas jaringan kejahatan transnasional yang semakin kompleks di kawasan Asia Tenggara. (Redaksi ASQINEWS).', 'Chief Editor', 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?auto=format&fit=crop&w=1000&q=80', 'Presiden RI Prabowo Subianto dan PM Thailand Anutin Charnvirakul saat bertemu di Istana Merdeka, Jakarta, Senin (3/8/2026). (Dok. Sekretariat Presiden)', '', '', 0, 0, '["Nasional"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785828667981', 'Ombudsman Mulai Nilai Pelayanan Publik KPU RI 2026, Fokus Cegah Maladministrasi dan Perkuat Layanan kepada Masyarakat', 'Pelayanan Publik', '4 AGUSTUS 2026, 14.31', 2, 'Ombudsman RI memulai Penilaian Maladministrasi Pelayanan Publik Tahun 2026 di KPU RI. Penilaian difokuskan pada pencegahan maladministrasi dan peningkatan kualitas pelayanan kepada masyarakat.', 'JAKARTA, ASQINEWS.com – Ombudsman Republik Indonesia mulai melaksanakan rangkaian Penilaian Maladministrasi Pelayanan Publik Tahun 2026 terhadap Komisi Pemilihan Umum (KPU) RI. Melalui kegiatan Entry Meeting yang digelar di Kantor KPU RI, Senin (3/8/2026), Ombudsman menegaskan bahwa penilaian tersebut bukan semata-mata untuk memberikan nilai atau peringkat, melainkan mendorong perbaikan kualitas pelayanan publik yang dirasakan langsung oleh masyarakat.\n\nAnggota Ombudsman RI Partono mengatakan, program penilaian tersebut merupakan instrumen pengawasan yang telah dijalankan Ombudsman selama lebih dari satu dekade untuk memperkuat tata kelola pelayanan publik di berbagai instansi pemerintah.\n\n"Tahun ini terdapat pendekatan baru melalui Penilaian Maladministrasi Pelayanan Publik. Namun indikator yang digunakan tetap mengacu pada empat dimensi penilaian, survei kepercayaan masyarakat, serta kepatuhan terhadap tindak lanjut Ombudsman, baik Laporan Hasil Analisis (LHA), Laporan Hasil Pemeriksaan (LHP), maupun saran penyempurnaan," ujar Partono.\n\nIa menegaskan, esensi penilaian bukanlah mengejar angka ataupun peringkat, melainkan memastikan pelayanan publik benar-benar memberi manfaat bagi masyarakat.\n\n"Kami berharap seluruh penyelenggara pelayanan publik terus meningkatkan kualitas layanan. Dampak yang ingin dicapai adalah masyarakat memperoleh pelayanan yang semakin baik dan setiap persoalan pelayanan dapat diselesaikan secara optimal," katanya.\n\nMenurut Partono, peningkatan kualitas pelayanan publik juga menjadi bagian dari dukungan terhadap agenda prioritas nasional yang dicanangkan Presiden. Karena itu, Ombudsman mendorong setiap instansi melakukan perbaikan pelayanan secara berkelanjutan.\n\nSementara itu, Anggota KPU RI Yulianto Sudrajat menyambut baik pelaksanaan penilaian tersebut. Menurutnya, pengawasan yang dilakukan Ombudsman merupakan bagian dari mekanisme untuk memastikan pelayanan publik di lingkungan KPU terus mengalami peningkatan.\n\n"Kami memandang penilaian ini sebagai sesuatu yang wajar karena memiliki tujuan yang sama, yakni memberikan pelayanan terbaik kepada masyarakat. Selain diawasi Ombudsman, KPU juga diawasi berbagai lembaga negara serta masyarakat secara langsung," ujar Yulianto.\n\nPada kesempatan yang sama, Anggota KPU RI Iffa Rosita menyampaikan bahwa peningkatan kualitas pelayanan publik menjadi salah satu prioritas KPU RI, termasuk dalam pembangunan Zona Integritas.\n\nIa mengungkapkan, lebih dari 95 persen pengaduan masyarakat yang disampaikan melalui aplikasi SPAN-LAPOR! telah ditindaklanjuti sebagai bentuk komitmen KPU dalam menghadirkan pelayanan yang cepat, responsif, dan akuntabel.\n\nSebagai tindak lanjut dari Entry Meeting tersebut, Ombudsman RI bersama KPU RI akan melakukan koordinasi intensif mulai akhir Agustus 2026 melalui person in charge (PIC) masing-masing. Tahapan ini menjadi bagian dari proses Penilaian Maladministrasi Pelayanan Publik Tahun 2026 yang diharapkan mampu memperkuat tata kelola pelayanan publik sekaligus meningkatkan kepercayaan masyarakat terhadap penyelenggara pelayanan publik.\n\nKegiatan tersebut turut diikuti jajaran KPU RI dari tingkat pusat, provinsi, kabupaten, dan kota secara luring maupun daring. (Redaksi ASQINEWS).\nSumber: Humas Oumbesmen RI', 'Chief Editor', 'https://images.unsplash.com/photo-1540910419892-4a36d2c3266c?auto=format&fit=crop&w=1000&q=80', 'Anggota Ombudsman RI Partono (tengah) bersama jajaran Komisi Pemilihan Umum (KPU) RI berfoto usai kegiatan Entry Meeting Penilaian Maladministrasi Pelayanan Publik Tahun 2026 di Kantor KPU RI, Jakarta, Senin (3/8/2026). Pertemuan tersebut menandai dimulainya rangkaian penilaian Ombudsman RI terhadap kualitas pelayanan publik di lingkungan KPU. Foto: Humas Ombudsman RI.', '', '', 1, 1, '["#Pelayanan publik oumbesmen KPU"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785830139026', 'Mendagri: Data Dukcapil Jadi Fondasi Layanan Publik Digital, Warga Kelak Tak Lagi Direpotkan Dokumen Fisik', 'Pelayanan Publik', '4 AGUSTUS 2026, 14.55', 3, 'Mendagri: Data Dukcapil Jadi Fondasi Layanan Publik Digital Nasional', 'Mendagri: Data Dukcapil Jadi Fondasi Layanan Publik Digital, Warga Kelak Tak Lagi Direpotkan Dokumen Fisik\n\nJAKARTA, ASQINEWS.com – Pemerintah menempatkan data kependudukan sebagai fondasi utama transformasi pelayanan publik berbasis digital. Melalui integrasi data Direktorat Jenderal Kependudukan dan Pencatatan Sipil (Dukcapil), masyarakat ke depan diharapkan dapat mengakses berbagai layanan pemerintah secara lebih cepat, mudah, dan tanpa harus berulang kali membawa dokumen administrasi.\n\nKomitmen tersebut ditegaskan Menteri Dalam Negeri Tito Karnavian saat membuka Rapat Koordinasi Nasional (Rakornas) Kependudukan dan Pencatatan Sipil Tahun 2026 di Hotel Bidakara, Jakarta, Senin (3/8/2026).\n\nMenurut Tito, keberhasilan penerapan Sistem Pemerintahan Berbasis Elektronik (SPBE) maupun implementasi Satu Data Indonesia sangat bergantung pada kualitas data kependudukan yang dimiliki Dukcapil.\n"Pangkalan data yang paling lengkap dan terus diperbarui adalah data Dukcapil. Karena itu, Dukcapil menjadi bagian penting dalam sistem pemerintahan digital yang sedang dibangun," ujar Tito.\n\nIa menjelaskan, basis data Dukcapil saat ini telah mencakup sekitar 290 juta penduduk atau hampir 99 persen populasi Indonesia. Selain memuat identitas dasar, sistem tersebut juga menyimpan data biometrik seperti sidik jari, pengenalan wajah, dan iris mata yang diperbarui secara real time dari seluruh Indonesia.\n\nSetiap perubahan data, mulai dari kelahiran, kematian, perkawinan hingga perpindahan domisili, langsung tercatat dalam sistem sehingga pemerintah memiliki basis data yang terus diperbarui.\n\nPangkas Birokrasi\n\nTito mengatakan, integrasi data kependudukan merupakan langkah strategis untuk memangkas birokrasi pelayanan publik. Ke depan, masyarakat cukup mengakses satu portal layanan digital untuk memperoleh berbagai layanan pemerintah, mulai dari administrasi kependudukan, pendidikan, kesehatan, bantuan sosial hingga layanan sektor lainnya.\n\nData Dukcapil juga akan diintegrasikan dengan berbagai kementerian dan lembaga, antara lain Kementerian Agraria dan Tata Ruang/Badan Pertanahan Nasional (ATR/BPN), Badan Pusat Statistik (BPS), Kepolisian RI, Kementerian Kesehatan, serta instansi pemerintah lainnya.\n\n"Data ini nantinya mempermudah masyarakat," kata Tito.\n\nSalah satu implementasi yang tengah disiapkan adalah integrasi layanan Dukcapil dengan fasilitas kesehatan. Melalui sistem tersebut, bayi yang lahir di rumah sakit atau puskesmas nantinya dapat langsung memperoleh akta kelahiran tanpa orang tua harus datang ke kantor Dinas Dukcapil.\n"Nantinya akta kelahiran bayi akan dikirim langsung ke email orang tua," ujar Tito.\n\nInfrastruktur Digital Diperkuat\n\nUntuk mendukung transformasi tersebut, pemerintah menyiapkan penguatan infrastruktur teknologi informasi Dukcapil melalui skema pembiayaan multiyears senilai sekitar Rp3,5 triliun.\n\nAnggaran tersebut akan digunakan untuk meningkatkan kapasitas pusat data, memperbesar bandwidth, memperkuat sistem keamanan siber, serta membangun pusat pencadangan data (disaster recovery center) agar pelayanan publik tetap berjalan apabila terjadi gangguan pada pusat data utama.\n\nMenurut Tito, keandalan sistem digital menjadi syarat mutlak agar pelayanan publik tidak terganggu.\n"Kalau sistemnya berhenti, pelayanan kepada masyarakat juga akan berhenti. Karena itu, kapasitas jaringan dan keamanan siber harus dipersiapkan secara maksimal," katanya.\n\nDukcapil Bertransformasi Menjadi Infrastruktur Pelayanan Publik\n\nRakornas Dukcapil 2026 juga menjadi momentum peluncuran Data Kependudukan Bersih (DKB) Semester I Tahun 2026 yang menjadi acuan berbagai kebijakan nasional.\nDirektur Jenderal Dukcapil Teguh Setyabudi mengatakan, integrasi data kependudukan akan membuat pelayanan publik semakin efektif sekaligus memastikan berbagai program pemerintah, termasuk penyaluran bantuan sosial, lebih tepat sasaran.\n\n"Melalui integrasi tersebut, penyaluran bantuan sosial diharapkan lebih tepat sasaran karena mengacu pada data kependudukan yang terus diperbarui," ujar Teguh.\n\nSelain itu, pemanfaatan Nomor Induk Kependudukan (NIK) dan Identitas Kependudukan Digital (IKD) akan menjadi fondasi Digital Public Infrastructure (DPI) Indonesia sehingga proses verifikasi identitas masyarakat dapat dilakukan secara elektronik dan real time.\n\nRakornas yang berlangsung pada 3–4 Agustus 2026 itu diikuti sekitar 700 peserta yang terdiri atas pejabat kementerian dan lembaga, pimpinan Kementerian Dalam Negeri, jajaran Ditjen Dukcapil, serta kepala dinas Dukcapil provinsi maupun kabupaten/kota dari seluruh Indonesia.\n\nMelalui forum tersebut, pemerintah mempertegas perubahan peran Dukcapil. Jika sebelumnya hanya berfungsi sebagai penyelenggara administrasi kependudukan, kini data kependudukan diposisikan sebagai infrastruktur dasar yang menopang ekosistem pelayanan publik digital di Indonesia. (Redaksi ASQINEWS)\nSumber : Humas Ditjen Dukcapil Kemendagri.', 'Chief Editor', 'https://images.unsplash.com/photo-1450133064473-71024230f91b?auto=format&fit=crop&w=1000&q=80', 'Menteri Dalam Negeri Tito Karnavian menyampaikan arahan saat membuka Rapat Koordinasi Nasional Kependudukan dan Pencatatan Sipil Tahun 2026 di Hotel Bidakara, Jakarta, Senin (3/8/2026). Dalam forum tersebut, Tito menegaskan data kependudukan Dukcapil menjadi fondasi utama pengembangan layanan publik digital dan integrasi data antarkementerian serta lembaga. Foto: Humas Ditjen Dukcapil Kemendagri.', '', '', 1, 1, '["Pelayanan publik Kemendagri dukcapil"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785831549234', 'Menteri PANRB Ubah Paradigma Arsiparis, Siap Jadi Penggerak Layanan Publik Digital', 'Pelayanan Publik', '4 AGUSTUS 2026, 15.19', 2, 'PANRB Ubah Paradigma Arsiparis, Dari Penjaga Dokumen Menjadi Analis Pelayanan Publik', 'JAKARTA, ASQINEWS.com – Pemerintah mulai mengubah paradigma profesi arsiparis di Indonesia. Jika selama ini arsiparis identik sebagai pengelola atau penjaga dokumen, ke depan mereka diproyeksikan menjadi analis informasi strategis yang mampu mengolah arsip menjadi dasar pengambilan kebijakan sekaligus mendorong peningkatan kualitas pelayanan publik.\n\nTransformasi tersebut menjadi salah satu fokus pembahasan Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi (PANRB) Rini Widyantini saat menggelar rapat pengembangan sumber daya manusia kearsipan bersama Arsip Nasional Republik Indonesia (ANRI) di Jakarta, Senin (3/8/2026).\n\nMenurut Rini, perkembangan teknologi digital telah mengubah wajah dunia kearsipan. Arsip tidak lagi dipandang sebagai kumpulan dokumen yang disimpan secara pasif, melainkan sebagai aset strategis yang dapat dianalisis untuk menghasilkan informasi penting bagi penyelenggaraan pemerintahan.\n\n"Kearsipan dunia mengalami disrupsi dampak dari perkembangan teknologi digital. Arsip tidak lagi dilihat sebagai tumpukan kertas statis, melainkan aset yang siap dianalisis secara digital," ujar Rini.\n\nIa menjelaskan, data yang tersimpan dalam arsip dapat menjadi sumber evaluasi berbagai program pemerintah, termasuk mengidentifikasi kelemahan dalam penyelenggaraan pelayanan publik. Melalui analisis terhadap arsip, pemerintah dapat mengetahui proses pelayanan yang belum berjalan optimal untuk kemudian diperbaiki.\n\nKarena itu, kompetensi arsiparis juga harus berkembang mengikuti perubahan zaman. Selain memahami prinsip-prinsip kearsipan, arsiparis kini dituntut memiliki kemampuan analisis data, memanfaatkan kecerdasan buatan (artificial intelligence/AI), serta menguasai teknologi digital.\n\nMenurut Rini, penguatan kompetensi tersebut menjadi bagian penting dari agenda transformasi birokrasi nasional yang tengah dijalankan pemerintah.\n\n"Transformasi digital tidak hanya mengubah cara kita bekerja, tetapi juga mengubah cara kita mengelola memori institusi. Karena itu, peran arsiparis harus terus diperkuat agar mampu memastikan setiap informasi pemerintah terdokumentasi secara autentik, aman, dan mudah diakses sebagai dasar pengambilan keputusan serta pelayanan kepada masyarakat," katanya.\n\nMeski digitalisasi terus berkembang, Rini menegaskan pengelolaan arsip fisik tetap harus dipertahankan untuk menjaga keaslian dokumen negara. Menurutnya, sistem pengelolaan arsip ke depan akan mengedepankan pendekatan hibrida sebagai bagian dari strategi layanan omnichannel yang dikembangkan pemerintah.\n\nDengan perubahan tersebut, arsiparis tidak lagi dipandang sebagai pengelola dokumen semata. Mereka diharapkan menjadi penjaga memori organisasi sekaligus pengelola informasi strategis yang mendukung transparansi, akuntabilitas, efektivitas pemerintahan, dan peningkatan kualitas pelayanan publik.\n\nSementara itu, Kepala ANRI Mego Pinandito mengatakan pihaknya tengah mempercepat transformasi digital kearsipan melalui proses alih media arsip dari bentuk analog ke digital. Langkah tersebut dilakukan tanpa mengabaikan perlindungan terhadap arsip fisik, khususnya arsip sejarah yang memiliki nilai autentik tinggi.\n\nSelain digitalisasi arsip, ANRI juga memperluas kerja sama dengan berbagai kementerian, lembaga, pemerintah daerah, hingga sektor swasta untuk meningkatkan kompetensi arsiparis melalui pelatihan teknis dan program magang bagi aparatur sipil negara di seluruh Indonesia.\n\nMenurut Mego, penguatan kompetensi digital menjadi salah satu prioritas agar arsiparis mampu mengikuti perkembangan teknologi sekaligus mendukung kebutuhan birokrasi modern.\n\n"Kami memasukkan pengetahuan dan keterampilan digital ke dalam peningkatan kompetensi kearsipan," ujarnya.\n\nKolaborasi antara Kementerian PANRB dan ANRI juga mencakup penyusunan kebijakan pengelolaan arsip yang adaptif terhadap perkembangan teknologi, termasuk pemanfaatan kecerdasan buatan dan sistem hibrida dalam tata kelola arsip pemerintahan.\n\nTransformasi tersebut diharapkan menjadikan arsip tidak hanya sebagai dokumen administrasi, tetapi sebagai sumber data strategis yang mampu mendukung perumusan kebijakan, mempercepat pengambilan keputusan, dan meningkatkan kualitas pelayanan publik di era pemerintahan digital. (Redaksi ASQINEWS).\nSumber : HUMAS MENPANRB', 'Chief Editor', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1000&q=80', 'Menteri Pendayagunaan Aparatur Negara dan Reformasi Birokrasi Rini Widyantini memimpin rapat pengembangan sumber daya manusia kearsipan bersama jajaran Arsip Nasional Republik Indonesia (ANRI) di Jakarta, Senin (3/8/2026). Pertemuan tersebut membahas transformasi peran arsiparis menjadi analis informasi strategis untuk mendukung birokrasi digital dan peningkatan kualitas pelayanan publik.', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?auto=format&fit=crop&w=1000&q=80', '', 1, 1, '["Panrb pelayanan publik ardiparis"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785831617872', 'Jasa Marga Perkuat Kepemimpinan Berbasis Pengalaman Pelanggan, Direksi Hingga Pimpinan Operasional Ikuti Pelatihan CX', 'Berita Terbaru', '4 AGUSTUS 2026, 15.20', 4, 'Program Customer Experience Leadership Series menempatkan pengalaman pelanggan sebagai bagian dari strategi bisnis, bukan sekadar layanan operasional.', 'JAKARTA, ASQINEWS.com — Transformasi pelayanan publik tidak cukup dilakukan melalui pembangunan infrastruktur dan pemanfaatan teknologi. Di tengah meningkatnya ekspektasi masyarakat terhadap kualitas layanan, kepemimpinan menjadi faktor yang menentukan apakah strategi benar-benar dirasakan manfaatnya oleh pelanggan.\n\nKesadaran itu menjadi salah satu fokus PT Jasa Marga (Persero) Tbk melalui penyelenggaraan Customer Experience Leadership Series yang diikuti jajaran direksi hingga pimpinan operasional perusahaan di Jakarta, Rabu (4/8/2026).\n\nProgram tersebut menghadirkan Ahmad Arwani Raharjo, Ketua Umum Asosiasi Service Quality Indonesia (ASQI) sekaligus pendiri ASQINEWS, sebagai fasilitator. Selama satu hari, peserta diajak membangun cara pandang baru bahwa pengalaman pelanggan (customer experience) bukan lagi sekadar urusan petugas layanan, melainkan bagian dari strategi bisnis yang harus dipimpin dari tingkat manajemen tertinggi.\n\n"Jalan tol hari ini tidak lagi hanya dinilai dari mulusnya aspal. Pelanggan menilai dari kecepatan informasi saat macet, kemudahan transaksi, hingga cara petugas berkomunikasi ketika memberikan bantuan," kata Arwani.\n\nMenurut dia, perubahan perilaku pelanggan menuntut perusahaan pengelola jalan tol untuk melihat pelayanan secara lebih menyeluruh. Pengalaman pengguna terbentuk dari setiap titik interaksi, mulai dari memperoleh informasi, melakukan transaksi, hingga memperoleh bantuan ketika menghadapi kendala di perjalanan.\n\nKarena itu, kepemimpinan tidak lagi hanya berorientasi pada pencapaian target operasional, tetapi juga pada kemampuan membangun budaya pelayanan yang konsisten di seluruh lini organisasi.\n\nProgram dibagi dalam dua pendekatan. Sesi pertama diperuntukkan bagi jajaran Board of Directors dengan materi yang menempatkan Customer Experience sebagai strategi bisnis. Peserta diajak memahami keterkaitan antara pengalaman pelanggan, keberlanjutan organisasi, serta budaya perusahaan yang berorientasi pada pelanggan.\n\nSementara itu, sesi berikutnya diperuntukkan bagi pimpinan unit kerja dengan penekanan pada implementasi CX100 melalui penyempurnaan proses pelayanan (process) dan penguatan kompetensi sumber daya manusia (people).\n\nDalam pelatihan tersebut digunakan kerangka CX100 yang dikembangkan Jasa Marga dengan tiga prinsip utama, yakni Effectiveness, Ease, dan Emotion. Ketiga prinsip itu dipadukan dengan Panduan Melayani Sepenuh Hati sebagai standar pelayanan bagi petugas operasional dan frontliner.\n\nPeserta juga mempelajari pendekatan RESPOND untuk meningkatkan kemampuan komunikasi empatik serta menangani keberatan pelanggan secara profesional.\n\nArwani menilai keberhasilan transformasi pelayanan tidak hanya ditentukan oleh tersusunnya prosedur kerja yang baik, tetapi juga oleh kemampuan setiap pemimpin menjadi penggerak perubahan di unit kerjanya masing-masing.\n\n"Strategi tanpa orang yang menjalankannya dengan hati tidak akan pernah sampai kepada pelanggan. Pemimpin harus menjadi sponsor perubahan itu," ujarnya.\n\nIa menambahkan, perusahaan dengan skala layanan sebesar Jasa Marga menghadapi tantangan yang semakin kompleks. Selain menjaga kualitas infrastruktur, perusahaan juga dituntut mampu mengelola persepsi publik yang terbentuk dari pengalaman pelanggan sehari-hari.\n\n"Perusahaan sebesar Jasa Marga tidak hanya mengelola jalan tol. Perusahaan juga mengelola kepercayaan publik. Dan kepercayaan itu dibangun dari ribuan interaksi kecil yang terjadi setiap hari," katanya.\n\nSeluruh peserta diminta menyusun komitmen perbaikan yang akan diterapkan di unit kerja masing-masing. Komitmen tersebut akan dievaluasi dalam tiga bulan mendatang untuk mengukur dampaknya terhadap peningkatan kualitas pelayanan.\n\n"Keberhasilan pelatihan ini bukan ketika sertifikat dibagikan, tetapi ketika tiga bulan kemudian pengguna jalan benar-benar merasakan perubahan kualitas pelayanan," ujar Arwani.\n\nCustomer Experience Leadership Series merupakan bagian dari upaya Jasa Marga memperkuat implementasi program CX100 secara berkelanjutan di lingkungan perusahaan dan anak usaha. Melalui program ini, perusahaan berupaya menyelaraskan perspektif kepemimpinan, proses bisnis, dan budaya kerja agar pengalaman pelanggan menjadi bagian yang tidak terpisahkan dari strategi perusahaan. (Redaksi ASQINEWS).', 'Super Admin ASQI', 'https://images.unsplash.com/photo-1545558014-8692077e9b5c?auto=format&fit=crop&w=1000&q=80', 'Peserta mengikuti Customer Experience Leadership Series yang diselenggarakan PT Jasa Marga (Persero) Tbk di Jakarta, Rabu (4/8/2026). Program yang difasilitasi Ahmad Arwani Raharjo tersebut diikuti jajaran direksi dan pimpinan operasional sebagai bagian dari penguatan implementasi Customer Experience (CX100) di lingkungan Jasa Marga', 'https://images.unsplash.com/photo-1573164713988-8665fc963095?auto=format&fit=crop&w=1000&q=80', '', 1, 1, '["Berita Terbaru"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785836505023', 'DKI Siap Berbagi Pengalaman Obligasi Daerah, Dorong Pelayanan Publik Lebih Berkualitas', 'Daerah', '4 AGUSTUS 2026, 16.41', 2, 'Pemprov DKI Jakarta siap berbagi pengalaman penerbitan obligasi daerah kepada Pemprov Bali sebagai bagian dari penguatan pembiayaan pembangunan dan peningkatan kualitas pelayanan publik.', 'JAKARTA, ASQINEWS.com – Pemerintah Provinsi DKI Jakarta dan Pemerintah Provinsi Bali memperkuat kerja sama pengembangan pembiayaan kreatif (creative financing) sebagai upaya mempercepat pembangunan sekaligus meningkatkan kualitas pelayanan publik di tengah keterbatasan ruang fiskal daerah.\n\nKomitmen tersebut mengemuka dalam pertemuan Gubernur DKI Jakarta Pramono Anung dengan Gubernur Bali I Wayan Koster dan Bupati Badung I Wayan Adi Arnawa di Balai Kota Jakarta, Selasa (4/8/2026). Salah satu pembahasan utama adalah kesiapan Pemprov DKI Jakarta berbagi pengalaman dalam proses penerbitan obligasi daerah sebagai alternatif pembiayaan pembangunan.\n\nPramono mengatakan pemerintah daerah perlu mencari sumber pembiayaan baru agar pembangunan dan pelayanan kepada masyarakat tidak sepenuhnya bergantung pada Anggaran Pendapatan dan Belanja Daerah (APBD).\n\n"Dalam kondisi ekonomi seperti sekarang, tantangan untuk meningkatkan APBD tidak bisa lagi dilakukan dengan cara-cara konvensional. Harus ada terobosan atau pendekatan out of the box," ujar Pramono.\n\nMenurut dia, DKI Jakarta saat ini tengah menyiapkan penerbitan obligasi daerah sebagai salah satu instrumen pembiayaan pembangunan. Pengalaman tersebut siap dibagikan kepada Pemerintah Provinsi Bali, mulai dari penyusunan kerangka kebijakan, koordinasi dengan kementerian dan lembaga terkait, hingga pemenuhan berbagai persyaratan regulasi.\n\nSelain obligasi daerah, kedua pemerintah daerah juga membahas berbagai instrumen pembiayaan lainnya, seperti pemanfaatan Koefisien Lantai Bangunan (KLB), Surat Persetujuan Prinsip Pembebasan Lokasi/Lahan (SP3L), serta skema pembiayaan inovatif lainnya yang dapat mendukung percepatan pembangunan daerah.\n\nPramono menegaskan, inovasi pembiayaan bukan semata bertujuan meningkatkan kapasitas fiskal daerah, melainkan memastikan program pembangunan dan pelayanan publik tetap berjalan secara berkelanjutan di tengah meningkatnya kebutuhan masyarakat.\n\nPertemuan tersebut juga menjadi bagian dari penguatan kerja sama antara DKI Jakarta dan Bali yang telah disepakati melalui Kesepakatan Bersama tentang Pengembangan Potensi Daerah dan Peningkatan Pelayanan Publik yang ditandatangani pada 10 Juli 2023.\n\nKerja sama tersebut mencakup pengembangan sektor kebudayaan, pariwisata, ekonomi kreatif, ketahanan pangan, peningkatan kompetensi sumber daya manusia, penguatan badan usaha milik daerah (BUMD), hingga pengembangan transportasi publik.\n\nPramono berharap sinergi yang telah terbangun tidak berhenti pada tingkat kebijakan, tetapi segera diwujudkan dalam program-program konkret yang memberikan manfaat langsung bagi masyarakat.\n\n"Harapannya kerja sama ini dapat segera diterjemahkan ke dalam langkah-langkah teknis sehingga hasilnya benar-benar dirasakan masyarakat, baik melalui pembangunan daerah maupun peningkatan kualitas pelayanan publik," katanya.\n\nSementara itu, Gubernur Bali I Wayan Koster menyampaikan apresiasi atas dukungan Pemerintah Provinsi DKI Jakarta dalam berbagi pengalaman terkait skema pembiayaan pembangunan.\n\nMenurut Koster, hasil pembahasan tersebut akan segera ditindaklanjuti oleh tim teknis agar proses penyusunan kebijakan berjalan lebih cepat tanpa mengabaikan ketentuan peraturan perundang-undangan.\n\n"Kami berterima kasih kepada Bapak Gubernur DKI beserta jajaran. Pembahasan ini akan segera kami tindak lanjuti di tingkat tim teknis agar prosesnya berjalan lebih cepat dengan tetap menyesuaikan regulasi yang berlaku," ujar Koster.\n\nKolaborasi tersebut diharapkan menjadi model kerja sama antarpemerintah daerah dalam mengembangkan pembiayaan inovatif yang tidak hanya memperkuat kapasitas fiskal, tetapi juga mempercepat penyediaan infrastruktur dan menghadirkan pelayanan publik yang lebih berkualitas bagi masyarakat. (Redaksi ASQINEWS).', 'Chief Editor', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1000&q=80', 'Gubernur DKI Jakarta Pramono Anung bersama Gubernur Bali I Wayan Koster memberikan keterangan kepada wartawan usai pertemuan di Balai Kota Jakarta, Selasa (4/8/2026). Pertemuan membahas pengembangan skema pembiayaan kreatif, termasuk obligasi daerah, untuk mendukung percepatan pembangunan dan peningkatan kualitas pelayanan publik. Foto: Humas Pemprov DKI Jakarta.', 'https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?auto=format&fit=crop&w=1000&q=80', '', 1, 1, '["#DKI #Bali #pelayananpublik #daerah"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-1785838159739', 'Ki Hajar Dewantara, Bapak Pendidikan Nasional yang Mengubah Wajah Pelayanan Publik', 'PROFIL TOKOH PELAYANAN', '4 AGUSTUS 2026, 17.09', 3, 'Ki Hajar Dewantara tidak hanya dikenal sebagai Bapak Pendidikan Nasional, tetapi juga pelopor pelayanan publik di bidang pendidikan yang memperjuangkan akses belajar bagi seluruh rakyat Indonesia.', 'JAKARTA, ASQINEWS.com – Ketika berbicara mengenai pelayanan publik, sebagian besar orang akan membayangkan rumah sakit, kantor pemerintahan, pelayanan administrasi kependudukan, atau transportasi umum. Padahal jauh sebelum Indonesia merdeka, konsep pelayanan publik telah diperjuangkan melalui bidang pendidikan. Salah satu tokoh yang meletakkan fondasi tersebut adalah Ki Hajar Dewantara.\n\nMelalui gagasan dan perjuangannya, Ki Hajar Dewantara mengubah pendidikan dari sebuah hak istimewa yang hanya dapat dinikmati kalangan tertentu menjadi hak seluruh rakyat. Karena itu, ia tidak hanya layak dikenang sebagai Bapak Pendidikan Nasional, tetapi juga sebagai pelopor pelayanan publik di bidang pendidikan di Indonesia.\n\nLahir dari Kalangan Bangsawan, Memilih Berjuang untuk Rakyat\n\nKi Hajar Dewantara lahir di Yogyakarta pada 2 Mei 1889 dengan nama Raden Mas Soewardi Soerjaningrat. Ia berasal dari lingkungan bangsawan Keraton Yogyakarta. Sebagai keturunan ningrat, ia memiliki kesempatan memperoleh pendidikan yang saat itu hampir mustahil dinikmati masyarakat pribumi.\n\nNamun, privilese tersebut justru membuka matanya terhadap ketimpangan sosial yang terjadi pada masa kolonial Belanda. Pendidikan hanya diberikan kepada kelompok tertentu, sedangkan sebagian besar rakyat tidak memperoleh kesempatan yang sama.\n\nKesadaran inilah yang kemudian mengubah arah hidupnya.\n\nKritik yang Mengubah Sejarah\n\nSelain aktif di dunia pendidikan, Ki Hajar Dewantara juga dikenal sebagai jurnalis. Ia menulis di berbagai surat kabar dan menggunakan media sebagai alat perjuangan.\n\nPada 1913, ia menulis artikel berjudul "Als Ik Eens Nederlander Was" atau "Seandainya Aku Seorang Belanda". Tulisan tersebut mengkritik keras pemerintah kolonial yang meminta rakyat jajahan membiayai perayaan kemerdekaan Belanda.\n\nTulisan itu mengguncang pemerintah kolonial. Akibatnya, Ki Hajar Dewantara bersama Ernest Douwes Dekker dan Tjipto Mangunkusumo diasingkan ke Belanda.\n\nNamun justru di negeri itulah pemikirannya mengenai pendidikan semakin berkembang.\n\nPendidikan Adalah Pelayanan Publik\n\nSepulang dari Belanda, Ki Hajar Dewantara mendirikan Perguruan Taman Siswa pada 3 Juli 1922.\n\nSekolah ini membawa gagasan yang sangat revolusioner.\n\nSemua anak memiliki hak memperoleh pendidikan.\n\nTidak peduli miskin ataupun kaya.\n\nTidak peduli bangsawan ataupun rakyat biasa.\n\nTidak peduli suku maupun agama.\n\nPrinsip tersebut merupakan bentuk pelayanan publik yang jauh melampaui zamannya. Pendidikan dipandang sebagai hak warga negara, bukan komoditas ataupun hak istimewa.\n\nMelalui Taman Siswa, ribuan anak pribumi memperoleh kesempatan belajar yang sebelumnya tertutup akibat sistem pendidikan kolonial yang diskriminatif.\n\nMengubah Cara Negara Melayani Rakyat\n\nBanyak orang mengenal semboyan Ki Hajar Dewantara:\n\n"Ing ngarso sung tulodo, ing madya mangun karso, tut wuri handayani."\n\nKalimat ini bukan sekadar filosofi pendidikan.\n\nDi dalamnya terkandung prinsip pelayanan publik modern.\n\nPemimpin harus memberi teladan.\n\nPemerintah harus hadir membangun semangat masyarakat.\n\nNegara harus memberi ruang agar rakyat berkembang.\n\nNilai-nilai tersebut kini menjadi prinsip dalam penyelenggaraan birokrasi modern yang berorientasi pada pelayanan.\n\nArsitek Pendidikan Nasional\n\nSetelah Indonesia merdeka, Ki Hajar Dewantara dipercaya menjadi Menteri Pengajaran pertama Republik Indonesia.\n\nIa tidak hanya membangun sekolah.\n\nIa membangun sistem.\n\nIa meletakkan dasar kebijakan pendidikan nasional, membentuk kurikulum, memperkuat peran guru, dan memastikan negara hadir dalam memberikan layanan pendidikan.\n\nKonsep pendidikan sebagai hak warga negara yang kini dijamin konstitusi tidak dapat dilepaskan dari pemikirannya.\n\nWarisan yang Tetap Hidup\n\nHampir setiap warga Indonesia pernah mendengar semboyan "Tut Wuri Handayani". Kalimat tersebut bahkan menjadi identitas Kementerian Pendidikan.\n\nNamun sesungguhnya warisan terbesar Ki Hajar Dewantara bukanlah semboyan itu.\n\nWarisan terbesarnya adalah cara pandang bahwa pelayanan publik harus memanusiakan manusia.\n\nPendidikan tidak boleh mempersulit.\n\nSekolah tidak boleh diskriminatif.\n\nNegara wajib hadir melayani seluruh warga tanpa membedakan status sosial.\n\nPemikiran itu tetap relevan hingga hari ini ketika pemerintah terus mendorong transformasi pelayanan publik berbasis digital, peningkatan kualitas pendidikan, serta pemerataan akses belajar hingga ke daerah terpencil.\n\nInspirasi bagi Pelayanan Publik Masa Kini\n\nDi tengah perkembangan teknologi dan tuntutan pelayanan publik yang semakin cepat, gagasan Ki Hajar Dewantara justru semakin menemukan relevansinya.\n\nTransformasi digital tidak boleh menghilangkan nilai kemanusiaan.\n\nKemajuan birokrasi tidak boleh menjauhkan negara dari rakyat.\n\nSebaliknya, inovasi harus digunakan untuk memastikan setiap warga memperoleh haknya secara mudah, adil, dan bermartabat.\n\nSemangat inilah yang menjadikan Ki Hajar Dewantara bukan sekadar tokoh pendidikan, melainkan salah satu pelopor pelayanan publik Indonesia.\n\nLebih dari satu abad setelah gagasan-gagasannya lahir, pemikiran Ki Hajar Dewantara masih menjadi pijakan penting dalam membangun birokrasi yang melayani, pendidikan yang inklusif, dan negara yang hadir untuk seluruh rakyat.\n(Redaksi ASQINEWS).', 'Chief Editor', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=1000&q=80', 'Ki Hajar Dewantara sumber foto : Wikipedia', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=1000&q=80', '', 1, 1, '["#tokohpelayananpublik #pahlawan"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-2', 'Proyek Gasifikasi Batu Bara ke Metanol BBC Beroperasi Penuh 2030', 'Energi', '29 JULI 2026, 20.52', 1890, 'PT Bumi Alam Chemical (BBC) menyatakan proyek gasifikasi batu bara menjadi metanol ditargetkan beroperasi penuh pada 2030.', 'PT Bumi Alam Chemical (BBC) mengonfirmasi bahwa progres pengerjaan fasilitas Dimethyl Ether (DME) dan gasifikasi batu bara menjadi metanol di Kalimantan Timur telah mencapai tahap konstruksi teknis utama.\n\nFasilitas hilirisasi ini ditargetkan beroperasi penuh pada kuartal kedua 2030 dengan kapasitas produksi mencapai 1,8 juta ton metanol per tahun.\n\nInisiatif ini diproyeksikan mampu mengurangi impor LPG dan bahan baku kimia nasional secara bermakna sekaligus mengoptimalkan cadangan batu bara kalor sedang.', 'Budi Santoso', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 0, '["Hilirisasi","Energi","Batu Bara","Metanol"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-3', 'GOTO Pangkas Target EBITDA Gojek Jadi Rp 1,5 Triliun Imbas Komisi 5%', 'KORPORASI', '29 JULI 2026, 20.38', 3103, 'PT GoTo Gojek Tokopedia Tbk memangkas target EBITDA yang disesuaikan pada segmen on-demand services Gojek.', 'PT GoTo Gojek Tokopedia Tbk (GOTO) merevisi pembaharuan panduan kinerja keuangan tahun berjalan untuk unit bisnis on-demand services (Gojek).\n\nPenyesuaian target EBITDA yang disesuaikan menjadi Rp 1,5 triliun dilakukan menyusul pemberlakuan batasan komisi mitra pengemudi maksimal 5% sesuai Perpres terbaru.\n\nManajemen GOTO menegaskan akan tetap mengoptimalkan efisiensi operasional dan penguatan lini layanan keuangan GoPay guna menjaga kurva pertumbuhan profitabilitas jangka panjang.', 'Ahmad Nurfajri', 'https://images.unsplash.com/photo-1521791136064-7986c2920216?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 1, '["GOTO","Gojek","Saham","Bursa","EBITDA"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-4', 'Viral Sinyal Turun ke 2G, Pakar Sebut Link Phishing Tetap Jadi Ancaman Utama', 'Teknologi', '29 JULI 2026, 20.34', 1650, 'Pakar keamanan siber menilai narasi yang terlalu menitikberatkan perubahan sinyal justru berpotensi menimbulkan pemahaman keliru.', 'Belakangan ini marak perbincangan di media sosial mengenai fenomena indikator sinyal ponsel yang tiba-tiba berpindah ke jaringan 2G saat menerima pesan misterius.\n\nPakar Keamanan Siber dari Communication & Information System Security Research Center (CISSReC) mengimbau masyarakat untuk tidak panik namun tetap waspada.\n\n"Ancaman utama pengurasan rekening pengguna sebenarnya terletak pada tautan APK palsu atau website phishing yang dikirim lewat rekayasa sosial (social engineering), bukan sekadar penurunan pita frekuensi sinyal," paparnya.', 'Dewi Lestari', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 0, '["CyberSecurity","Phishing","Teknologi","Siber"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-5', 'Daftar Saham Pembagi Dividen Jumbo ADRO, ANTM dan BBCA, Intip Rekomendasi Analis', 'Berita Terbaru', '29 JULI 2026, 19.30', 4500, 'Sejumlah emiten papan atas menjadwalkan pembagian dividen interim dengan yield menarik di kuartal ketiga.', 'Pasar modal Indonesia disambut sentimen positif dari pengumuman dividen interim emiten bluechip.\n\nPT Adaro Energy Indonesia Tbk (ADRO), PT Aneka Tambang Tbk (ANTM), dan PT Bank Central Asia Tbk (BBCA) siap membagikan sebagian keuntungan bersih tahun buku 2026 kepada para pemegang saham.\n\nAnalis sekuritas merekomendasikan strategi akumulasi beli secara bertahap menjelang kumulatif date (cum date) untuk mengamankan imbal hasil dividen yang diproyeksikan melebihi tingkat inflasi tahunan.', 'Analis Finansial', 'https://images.unsplash.com/photo-1590283603385-17ffb3a7f29f?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 1, '["Saham","Dividen","BBCA","ADRO","ANTM"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-6', 'Sembcorp Utilities Beri Sinyal Akuisisi 20% Saham Entitas Prajogo (TPIA)', 'Bisnis', '29 JULI 2026, 19.15', 3820, 'Raksasa energi asal Singapura menyatakan ketertarikan memperluas portofolio energi terbarukan di Indonesia.', 'Raksasa solusi energi terintegrasi Singapura, Sembcorp Utilities, membuka peluang investasi strategis di entitas petrochemical milik taipan Prajogo Pangestu, PT Chandra Asri Pacific Tbk (TPIA).\n\nLangkah akuisisi minoritas sebesar 20% ini bertujuan mempercepat transformasi penyediaan daya bersih dan fasilitas daur ulang polimer ramah lingkungan di Asia Tenggara.', 'Tim Keuangan', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 1, '["TPIA","Sembcorp","Finansial","Akuisisi"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-8', 'Geliat Saham Grup Harita NCKL Usai Masuk Indeks LQ45 dan IDX80, Cek Prospeknya', 'Bisnis', '29 JULI 2026, 17.40', 2950, 'Inklusi saham NCKL ke indeks utama memicu akumulasi pembelian oleh investor institusional domestik maupun asing.', 'Kinerja perdagangan saham PT Trimegah Bangun Persada Tbk (NCKL) mencatatkan lonjakan volume setelah rebalancing kuartalan Bursa Efek Indonesia menempatkannya dalam jajaran konstituen LQ45.\n\nAnalis memandang positif pengoperasian smelter HPAL tahap II yang diperkirakan mendongkrak margin laba bersih pemrosesan nikel kadar rendah.', 'Rian Hidayat', 'https://images.unsplash.com/photo-1526304640581-d334cdbbf45e?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 1, '["NCKL","LQ45","Harita","Bursa"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);
INSERT INTO `articles` (`id`, `title`, `category`, `publishedAt`, `views`, `snippet`, `content`, `author`, `image`, `imageCaption`, `middleImage`, `middleImageCaption`, `isFeatured`, `isPopular`, `tags`) VALUES ('art-9', 'Beda Nasib 4 Investor Milik Singapura, Malaysia, RI Kala Rugi Investasi Startup', 'Berita Terbaru', '29 JULI 2026, 16.20', 2780, 'Perbandingan strategi evaluasi aset dan manajemen risiko dari sovereign wealth fund regional menghadapi siklus tech winter.', 'Dinamika portofolio modal ventura di kawasan Asia Tenggara mengalami penyesuaian nilai wajar (write-down) seiring moderasi valuasi perusahaan rintisan.\n\nLaporan riset terbaru membandingkan pendekatan pemulihan investasi antara Temasek, Khazanah Nasional, dan konsorsium BUMN Indonesia dalam mendiversifikasi instrumen berisiko tinggi.', 'Maya Indah', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=300&q=80', '', '', '', 0, 1, '["Finansial","Startup","Ventura","Investasi"]') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `image`=VALUES(`image`);

